import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.44aEvdQQ.js";const h=JSON.parse('{"title":"The Two Calls System","description":"","frontmatter":{"title":"The Two Calls System","order":7,"subtitle":"Daily rhythm that operationalizes commitment and boundaries"},"headers":[],"relativePath":"about/chapters/07-the-two-calls-system.md","filePath":"about/chapters/07-the-two-calls-system.md"}'),i={name:"about/chapters/07-the-two-calls-system.md"};function l(n,e,r,m,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o("<p><em>Daily rhythm that operationalizes commitment and boundaries</em></p><p>Check-in (start of day): 15 minutes max, review today&#39;s commitments only across all active projects. Not Wednesday tasks on Monday. Creating commitment to each other, clients, selves. Checkout (4:45pm for 5pm end): What got done? Sweeping status into these two moments instead of constant texting/checking. What this accomplishes:</p><ul><li>Replaces surveillance with trust systems</li><li>Creates professional excellence during work hours</li><li>Mandates separation when not at work (vs Gen X owner texting at 6pm)</li><li>Scales beautifully (10 projects, 15 minutes, clarity)</li></ul><p>Operationalizing the operating value: when you&#39;re at work, give 100%. When you&#39;re not, we don&#39;t want you thinking about it.</p><blockquote><p>&quot;Delays in feedback loops can mask important, often critical, system information and system dynamics. Management must be aware of the delays.&quot;</p><ul><li><em>Simple_Complexity</em> by William Donaldson</li></ul></blockquote><blockquote><p>&quot;Managers often try to shape or limit the feedback the employees see. This is usually a futile effort since participants in the system often see, or sense, the real feedback. Additionally, systems often hide critical feedback with delays, which mask real results and consequences.&quot;</p><ul><li><em>Simple_Complexity</em> by William Donaldson</li></ul></blockquote>",6)])])}const d=t(i,[["render",l]]);export{h as __pageData,d as default};
